function getLexmachinaTranslation(key, lang) {
    if (lexmachinaTranslations[lang] && lexmachinaTranslations[lang][key]) {
        return lexmachinaTranslations[lang][key];
    }
    if (lexmachinaTranslations.en && lexmachinaTranslations.en[key]) {
        return lexmachinaTranslations.en[key];
    }
    return null;
}

function applyLexmachinaTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.lex-machina.')) {
            const translation = getLexmachinaTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyLexmachinaTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyLexmachinaTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyLexmachinaTranslations(currentLang);
}


